import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import api from "../services/api";
import TweetList from "../components/walls/tweetList";
import { API_ENDPOINTS } from "../services/apiEndpoints";
import Footer from "../components/footer.js";
import { DragDropContext, Droppable, Draggable } from "react-beautiful-dnd";

const Tweets = () => {
  const { wallId } = useParams();
  const navigate = useNavigate();
  const [tweets, setTweets] = useState(null);
  const [wall, setWall] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const logoUrl = "/path-to-logo.png"; // Fallback logo if wall.logo is unavailable

  useEffect(() => {
    const fetchWalls = async () => {
      try {
        let response = await api.get(API_ENDPOINTS.GET_TWEETS_BY_WALL(wallId));
        setTweets(response.data);
        response = await api.get(API_ENDPOINTS.GET_WALL_BY_ID(wallId));
        setWall(response.data);
        setLoading(false);
      } catch (err) {
        setError("Failed to load wall");
        setLoading(false);
      }
    };
    fetchWalls();
  }, [wallId]);

  if (loading) return <div>Loading...</div>;
  if (error) return <div>{error}</div>;
  if (!tweets) return <div>Wall not found</div>;

  const handleSaveOrder = async () => {
    try {
        await api.put(API_ENDPOINTS.UPDATE_TWEET_ORDER(wallId), { tweets });
        console.log("Tweet order saved:", tweets); // Debug log
    } catch (err) {
        setError("Failed to save tweet order");
        console.error("Error saving tweet order:", err);
    }
};

const onDragEnd = (result) => {
    const { source, destination } = result;

    // If dropped outside the list or in the same position, do nothing
    if (!destination || destination.index === source.index) {
        return;
    }

    // Reorder the tweets array
    const newTweets = Array.from(tweets);
    const [reorderedItem] = newTweets.splice(source.index, 1);
    newTweets.splice(destination.index, 0, reorderedItem);

    // Update with new order (using index as order if no id-based order exists)
    setTweets(newTweets);
}

  return (
        <div className="p-6">
            <h2 className="text-2xl font-bold mb-4">Manage Tweets for Wall {wallId}</h2>
            <DragDropContext onDragEnd={onDragEnd}>
                <Droppable droppableId="tweets">
                    {(provided) => (
                        <div
                            ref={provided.innerRef}
                            {...provided.droppableProps}
                        >
                            {tweets.map((tweet, index) => (
                                <Draggable
                                    key={tweet.id || String(index)} // Use tweet.id if available, otherwise index
                                    draggableId={tweet.id || String(index)}
                                    index={index}
                                >
                                    {(provided) => (
                                        <div
                                            ref={provided.innerRef}
                                            {...provided.draggableProps}
                                            {...provided.dragHandleProps}
                                            className="flex space-x-2 mb-2 items-center bg-gray-100 p-2 rounded"
                                        >
                                            <span className="flex-1">
                                                {tweet.text || "No tweet text"} {/* Adjust based on your tweet structure */}
                                            </span>
                                            <button
                                                type="button"
                                                onClick={() => {
                                                    setTweets(tweets.filter((_, i) => i !== index));
                                                }}
                                                className="bg-red-500 text-white px-2 py-1 rounded hover:bg-red-600"
                                            >
                                                Remove
                                            </button>
                                        </div>
                                    )}
                                </Draggable>
                            ))}
                            {provided.placeholder}
                        </div>
                    )}
                </Droppable>
            </DragDropContext>
            <button
                onClick={handleSaveOrder}
                className="bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600 mt-4"
            >
                Save Tweet Order
            </button>
            <button
                onClick={() => navigate(`/walls/${wallId}/edit`)}
                className="bg-gray-500 text-white px-4 py-2 rounded hover:bg-gray-600 mt-2 ml-2"
            >
                Back to Edit Wall
            </button>
        </div>
    );
};

export default WallTweets;
